-- Kratos Labs — catalogo Deus Medical (categorie + prodotti + prezzo di acquisto).
-- Esegui nel dashboard Supabase: SQL Editor -> New query -> Run.
-- Prezzi: price_cents = RETAIL (vendita), cost_cents = DROP SHIPPING (acquisto).

-- 1) Colonna costo per il calcolo dei profitti.
alter table public.products
  add column if not exists cost_cents integer not null default 0 check (cost_cents >= 0);

-- 2) Rimuove le vecchie categorie di esempio (i prodotti collegati restano, senza categoria).
delete from public.categories
  where slug in ('proteine','creatina','pre-workout','elettroliti','omega-3','vitamine');

-- 3) Nuove categorie del listino Deus Medical.
on conflict (slug) do update set
  name = excluded.name, description = excluded.description, position = excluded.position, active = true;

-- 4) Prodotti. price_cents = vendita (RETAIL), cost_cents = acquisto (DROP SHIPPING).
--    I prodotti senza prezzo nel listino sono caricati come non attivi (stock 0).
on conflict (slug) do update set
  brand = excluded.brand, title = excluded.title, short_description = excluded.short_description,
  description = excluded.description, category = excluded.category, price_cents = excluded.price_cents,
  cost_cents = excluded.cost_cents, specs = excluded.specs, updated_at = now();
